package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.FeedbackService; import java.util.List; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/v1/answers/{answerId}/feedback") public class FeedbackController { private final FeedbackService service; public FeedbackController(FeedbackService s){service=s;} @GetMapping public List<FeedbackResponse> byAnswer(@PathVariable Integer answerId){return service.byAnswer(answerId).stream().map(FeedbackResponse::from).toList();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public FeedbackResponse create(@PathVariable Integer answerId,@Valid @RequestBody FeedbackRequest r){return FeedbackResponse.from(service.create(answerId,r));} }
